// Extract & Group (ES) — implements: checkov, trufflehog, zaproxy, kubescape, trivy
// Input: ES "Get many documents" items (each at item.json.Document)
//
// Grouping KEYS (normalized, owner included everywhere):
//   - checkov:    checkov|<pluginid>|<repo>|<owner>
//   - trufflehog: trufflehog|<owner>|<repo>|<file_path>|<pluginid>|<secret_digest>
//   - zaproxy:    zaproxy|<pluginid>|<origin>|<owner>
//   - kubescape:  kubescape|<pluginid>|<repo>|<owner>
//   - trivy:      trivy|<pluginid>|<pkg>|<fixedver>|<image>|<owner>
//
// Summaries:
//   - checkov:    "<owner> - <title>"
//   - trufflehog: "<owner> - <file_path>"   (OLD summary)
//   - zaproxy:    "<title> - <owner>"
//   - kubescape:  "<owner> - <title>"
//   - trivy:      "<owner> - <title>"
//
// Global:
//   - Drop items where severity == "Informational" (case-insensitive)
//   - Mitigating controls: Checkov filters out GitHub links
//   - Assets: Checkov aggregates ALL unique file paths; ZAP aggregates endpoints; Trivy uses Image
//
// Output per group:
//   {
//     tool, summary, site_owner_sanitized,
//     combinedCWEs,                       // TVI
//     combinedDescriptions,               // DEDUPED: "Docs: id1, id2" header + unique body
//     combinedReferencesWithTicket,       // DEDUPED: "Docs: id1, id2" header + unique ref content
//     risk_source, asset_urls
//   }

const uniq = a => Array.from(new Set((a || []).filter(Boolean)));
const uniqJoin = a => uniq(a).join("\n\n");
const sanitizeOwner = s => String(s || "").trim().replace(/\s+/g, "-");

// ---- case/normalization helpers ----
const norm = s => String(s || "").trim().toLowerCase();
const capFirst = s => {
  const t = String(s || "");
  return t ? t.charAt(0).toUpperCase() + t.slice(1).toLowerCase() : t;
};

function normRepo(u) {
  if (!u) return "";
  let s = String(u).trim();
  try {
    const url = new URL(s);
    return `${url.protocol}//${url.host}${url.pathname.replace(/\/+$/,'')}`.toLowerCase();
  } catch {
    return s.replace(/\/+$/,'').toLowerCase();
  }
}

function normPath(p) {
  const s = String(p || "").trim();
  return s.replace(/\\/g, "/").replace(/\/{2,}/g, "/");
}

function urlToOrigin(u) {
  if (!u) return "";
  const s = String(u).trim();
  const m = s.match(/^(https?:\/\/)?([^\/\s]+)/i);
  if (!m) return "";
  const scheme = (m[1] || "https://").toLowerCase().replace(/\/+$/,'');
  const host = m[2].toLowerCase();
  return `${scheme}//${host}`;
}

const isGithubUrl = v => /(^https?:\/\/)?(www\.)?github\.com/i.test(String(v || ""));

function readLine(desc, label) {
  const re = new RegExp(`^${label}\\s*:\\s*(.+)$`, "mi");
  const m = re.exec(String(desc || ""));
  return m ? m[1].trim() : null;
}

function cweToken(raw) {
  const n = String(raw ?? "").trim();
  if (!n) return "";
  const id = parseInt(n, 10);
  if (!Number.isFinite(id) || id <= 0) return "";
  return `CWE-${id} (https://cwe.mitre.org/data/definitions/${id}.html)`;
}

// ---- aggregators ----
const groups = new Map();

for (const it of items) {
  const d = it?.json?.Document || {};
  const tool = String(d.tool || "").toLowerCase();
  if (!tool) continue;

  if (!["checkov","trufflehog","zaproxy","kubescape","trivy"].includes(tool)) continue;

  // Global: skip Informational
  if (d.severity && /^informational$/i.test(String(d.severity))) continue;

  // Common fields
  const docId     = it.json?._id || "";
  const ownerRaw  = d.site_owner || readLine(d.description, "Repo Owner") || "";
  const ownerKey  = norm(ownerRaw);
  const ownerDisp = String(ownerRaw || "Owner");
  const title     = d.title || readLine(d.description, "Check Name") || readLine(d.description, "Control") || "";
  const severity  = d.severity || readLine(d.description, "Severity") || "";

  // Repo (preferred from dedupe.signature.repo, else first endpoint, else desc line)
  const repoRaw = d?.dedupe?.signature?.repo || (Array.isArray(d.endpoints) && d.endpoints[0]) || d.endpoints || readLine(d.description, "Repo Link") || "";
  const repoKey = normRepo(repoRaw);

  // ZAP origin/method/param
  const sigUrl   = d?.dedupe?.signature?.url || (Array.isArray(d.endpoints) && d.endpoints[0]) || d.endpoints || "";
  const origin   = urlToOrigin(sigUrl);
  const method   = String(d?.dedupe?.signature?.method || d.method || "").toUpperCase() || "-";
  const param    = String(d?.dedupe?.signature?.param || d.param || "").trim() || "-";

  // File path / trivy fields
  const filePathRaw = d.file_path || readLine(d.description, "File") || "";
  const filePathKey = normPath(filePathRaw);

  const pkg        = d.pkg || readLine(d.description, "Package") || "";
  const fixedver   = d.fixedVersion || readLine(d.description, "Fixed") || "";
  const image      = d?.dedupe?.signature?.image || readLine(d.description, "Image") || "";
  const imageid    = d?.image?.imageId || "";
  const pluginid   = d.pluginid || readLine(d.description, "Check Id") || "";
  const secretDig  = d?.dedupe?.signature?.secret_digest || "";

  const guidance   = d.guidance || d.references || readLine(d.description, "Guideline") || readLine(d.description, "Rotation Guide") || "";
  const endpoints  = Array.isArray(d.endpoints) ? d.endpoints : (d.endpoints ? [d.endpoints] : []);

  // Build grouping key by tool
  let gk = "";
  if (tool === "checkov") {
    gk = `checkov|${norm(pluginid)}|${repoKey}|${ownerKey}`;
  } else if (tool === "trufflehog") {
    gk = `trufflehog|${ownerKey}|${repoKey}|${norm(filePathKey)}|${norm(pluginid)}|${norm(secretDig)}`;
  } else if (tool === "zaproxy") {
    gk = `zaproxy|${norm(pluginid)}|${norm(origin)}|${ownerKey}`;
  } else if (tool === "kubescape") {
    gk = `kubescape|${norm(pluginid)}|${repoKey}|${ownerKey}`;
  } else if (tool === "trivy") {
    gk = `trivy|${norm(pluginid)}|${norm(pkg)}|${norm(fixedver)}|${norm(image)}|${ownerKey}`;
  }

  if (!gk) continue;

  if (!groups.has(gk)) {
    groups.set(gk, {
      tool,
      ownerDisp,
      title,
      pluginid,
      repoRaw,
      filePathRaw,
      image,
      imageid,
      origin,
      ids: [],
      assets: [],
      sources: [],
      tvis: [],
      descMap: new Map(), // dedupe descriptions { key -> { ids:[], body } }
      refMap:  new Map(), // dedupe references  { key -> { ids:[], body } }
      summaryBuilder:
        tool === "zaproxy"
          ? () => `${title || "Finding"} - ${ownerDisp}`
          : tool === "trufflehog"
            ? () => `${ownerDisp} - ${filePathRaw || "file"}`
          : tool === "kubescape"
            ? () => `${title || "Kubescape Alert"} - ${ownerDisp}`
            : () => `${ownerDisp} - ${title || "Finding"}`,
    });
  }

  const G = groups.get(gk);

  // ---- Description dedupe ----
  {
    const bodyParts = [];
    if (severity) bodyParts.push(`Severity: ${severity}`);
    const bodyText = [
      bodyParts.join("\n"),
      String(d.description || "").trim()
    ].filter(Boolean).join("\n\n").trim();

    if (bodyText) {
      const normKey = bodyText.replace(/\s+/g, " ").trim().toLowerCase();
      const entry = G.descMap.get(normKey) || { ids: [], body: bodyText };
      entry.ids.push(docId);
      G.descMap.set(normKey, entry);
    }
  }

  // ---- References dedupe ----
  const addRef = (refText) => {
    const body = String(refText || "").trim();
    if (!body) return;
    const normKey = body.replace(/\s+/g, " ").trim().toLowerCase();
    const entry = G.refMap.get(normKey) || { ids: [], body };
    entry.ids.push(docId);
    G.refMap.set(normKey, entry);
  };

  if (tool === "checkov") {
    if (guidance && !isGithubUrl(guidance)) addRef(guidance);
  } else if (tool === "trufflehog") {
    // do NOT add repo link; only add guidance if present
    if (guidance) addRef(guidance);
    // if no guidance, we'll inject a default in the emit phase
  } else if (tool === "trivy") {
    if (guidance) addRef(guidance);
    for (const e of endpoints) if (e) addRef(e);
  } else if (tool === "kubescape") {
    if (pluginid) addRef(`https://hub.armosec.io/docs/${String(pluginid).toLowerCase()}`);
  } else if (tool === "zaproxy") {
    // capture ZAP references (array or string; may contain HTML with multiple links)
    const zr = d.references;
    const pushZapRef = (val) => {
      if (!val) return;
      const str = String(val);

      // Try to extract URLs from HTML/text
      const urls = [...str.matchAll(/https?:\/\/[^\s<>"')]+/gi)].map(m => m[0]);
      if (urls.length) {
        for (const u of urls) addRef(u);
        return;
      }

      // Fallback: split on common separators and tags
      str
        .split(/<\/p>\s*<p>|<br\s*\/?>|\n|;|,/gi)
        .map(s => s.trim())
        .filter(Boolean)
        .forEach(addRef);
    };

    if (Array.isArray(zr)) zr.forEach(pushZapRef);
    else pushZapRef(zr);
  }

  // ---- Assets Affected ----
  if (tool === "checkov") {
    if (filePathRaw) G.assets.push(normPath(filePathRaw));
  } else if (tool === "zaproxy") {
    for (const e of endpoints) if (e) G.assets.push(e);
  } else if (tool === "trufflehog") {
    if (filePathRaw) G.assets.push(normPath(filePathRaw));
  } else if (tool === "kubescape") {
    // ✅ Prefer resources from dedupe.signature.resources; fallback to resource_ids; else repo
    const ksRes = d?.dedupe?.signature?.resources;
    const ksResArr = Array.isArray(ksRes) ? ksRes.filter(Boolean) : (ksRes ? [ksRes] : []);
    const ksResIds = Array.isArray(d.resource_ids) ? d.resource_ids.filter(Boolean) : (d.resource_ids ? [d.resource_ids] : []);
    if (ksResArr.length) {
      G.assets.push(...ksResArr);
    } else if (ksResIds.length) {
      G.assets.push(...ksResIds);
    } else if (repoRaw) {
      G.assets.push(repoRaw);
    }
  } else if (tool === "trivy") {
    if (imageid) G.assets.push(imageid);
  }

  // ---- Risk Identification Source ----
  if (tool === "zaproxy") {
    if (origin) G.sources.push(origin);
  } else if (tool === "checkov") {
    if (repoRaw) G.sources.push(repoRaw);
  } else if (tool === "trufflehog") {
    if (filePathRaw) G.sources.push(normPath(filePathRaw));
    else if (repoRaw) G.sources.push(repoRaw);
  } else if (tool === "kubescape") {
    if (repoRaw) G.sources.push(repoRaw);
  } else if (tool === "trivy") {
    if (image) G.sources.push(image)
    else if (imageid) G.sources.push(imageid);
  }

  // ---- Threat & Vulnerability Info (TVI) ----
  if (tool === "zaproxy") {
    const tvi = cweToken(d.cwe);
    if (tvi) G.tvis.push(tvi); else if (pluginid) G.tvis.push(String(pluginid));
  } else if (tool === "kubescape") {
    if (pluginid) G.tvis.push(String(pluginid));
  } else {
    if (pluginid) G.tvis.push(String(pluginid));
  }

  G.ids.push(docId);
}

// ---- emit results ----
const out = [];
for (const [, G] of groups) {
  // DEDUPED descriptions
  const descBlocks = [];
  for (const { ids, body } of G.descMap.values()) {
    const idHeader = `Docs: ${ids.join(", ")}`;
    descBlocks.push(`${idHeader}\n\n${body}`);
  }

  // DEDUPED references
  const refBlocks = [];
  for (const { ids, body } of G.refMap.values()) {
    const idHeader = `Docs: ${ids.join(", ")}`;
    refBlocks.push(`${idHeader}\n\n${body}`);
  }

  // If trufflehog has no guidance refs, insert default best-practice message
  const combinedRefs =
    refBlocks.length
      ? refBlocks.join("\n\n")
      : (G.tool === "trufflehog"
          ? "Secrets and passwords should be stored in a secure vault and/or secure storage."
          : "");

  out.push({
    json: {
      tool: capFirst(G.tool),                                   // First letter uppercase only
      summary: G.summaryBuilder(),
      site_owner_sanitized: capFirst(sanitizeOwner(G.ownerDisp)),// First letter uppercase only
      combinedCWEs: uniqJoin(G.tvis),
      combinedDescriptions: descBlocks.join("\n\n"),
      combinedReferencesWithTicket: combinedRefs,
      risk_source: (uniq(G.sources)[0] || ""),
      asset_urls: uniq(G.assets).join("\n") || "",
    }
  });
}

return out;

// Create Update Payload (no rrdKey / no sourceKey; seed description only if blank)
// In #1: issues from "Get RRD Issue" (RRD)
// In #2: optional Set { forceUpdate: true }
// Reads grouped data from node named EXACTLY "Decide_Update/Create"

const FORCE_UPDATE_DEFAULT = false;
const toggleInput = $input.all(1);
const FORCE_UPDATE = (toggleInput?.[0]?.json?.forceUpdate ?? FORCE_UPDATE_DEFAULT) === true;

const decideItems = ($items("Decide_Update/Create") || []).map(i => i.json || {});
const byExistingKey = new Map();
const bySummary     = new Map();
for (const d of decideItems) {
  if (d?.existingKey) byExistingKey.set(String(d.existingKey), d);
  if (d?.summary)     bySummary.set(String(d.summary), d);
}

// helpers
const sameText  = (a,b) => String(a ?? "").trim() === String(b ?? "").trim();
const sameArray = (a=[],b=[]) => {
  if (a.length !== b.length) return false;
  const A=[...a].sort(), B=[...b].sort();
  for (let i=0;i<A.length;i++) if (A[i]!==B[i]) return false;
  return true;
};
const combineBlocks = (a,b) => {
  const A=String(a||"").split(/\n{2,}/).map(s=>s.trim()).filter(Boolean);
  const B=String(b||"").split(/\n{2,}/).map(s=>s.trim()).filter(Boolean);
  return Array.from(new Set([...A, ...B])).join("\n\n");
};
function normalizeLabel(s){
  if (!s) return null;
  const canon = { trufflehog:"Trufflehog", zaproxy:"Zaproxy", securityhub:"SecurityHub", checkov:"Checkov", prowler:"Prowler", kubescape:"Kubescape" };
  const t = String(s).trim(); if (!t) return null;
  const k = t.toLowerCase(); return canon[k] || t;
}
function uniqLabels(arr){
  const seen=new Set(), out=[];
  for (const raw of arr||[]){
    const norm = normalizeLabel(raw); if (!norm) continue;
    const k = norm.toLowerCase(); if (seen.has(k)) continue;
    seen.add(k); out.push(norm);
  }
  return out;
}
function capText(str, max=32767){
  const s=String(str||"");
  if (s.length<=max) return s;
  const paras=s.split(/\n{2,}/); let cur="";
  for (const p of paras){
    const trial = cur ? cur + "\n\n" + p : p;
    if (trial.length + 3 > max) break;
    cur = trial;
  }
  return (cur || s.slice(0, max-3)) + "...";
}

const SEED_DESC = "Likelihood/Probability:\nImpact/Severity:\nResidual Risk:";

const out = [];

for (const it of $input.all()) {
  const ex      = it.json || {};
  const key     = ex.key;
  const fields  = ex.fields || {};
  const summary = fields.summary || "";

  const grp = byExistingKey.get(String(key)) || bySummary.get(String(summary));
  if (!grp) continue;

  // current Jira
  const exDesc   = fields.description || "";
  const exDOR    = fields.customfield_10066 || "";
  const exRefs   = fields.customfield_10067 || "";
  const exRisk   = fields.customfield_10063 || "";
  const exAssets = fields.customfield_10065 || "";
  const exTVI    = fields.customfield_10064 || "";
  const exLabels = fields.labels || [];

  // new merged (same as before EXCEPT description behavior)
  const newDOR     = combineBlocks(exDOR,  grp.combinedDescriptions || "");
  const refsMerged = combineBlocks(exRefs,  grp.combinedReferencesWithTicket || "");
  const newRisk    = grp.risk_source || "";
  const newAssets  = combineBlocks(exAssets, grp.asset_urls || "");
  const newTVI     = combineBlocks(exTVI,    grp.combinedCWEs || "");
  const refsSafe   = capText(refsMerged, 32767);

  // labels
  const ownerLabel = String(grp.site_owner_sanitized || "").trim() || null;
  const toolLabel =
    /^\s*Prowler\s*Alert/i.test(String(grp.summary||""))   ? "Prowler"    :
    /^\s*https?:\/\//i.test(String(grp.summary||""))       ? "Zaproxy"    :
    /securityhub/i.test(String(grp.summary||""))           ? "SecurityHub":
    /checkov/i.test(String(grp.summary||""))               ? "Checkov"    :
    /kubescape/i.test(String(grp.summary||""))             ? "Kubescape"  :
    /trufflehog/i.test(String(grp.summary||""))            ? "Trufflehog" : "Trufflehog";
  const newLabels  = uniqLabels([ ...exLabels, ownerLabel, toolLabel ]);

  // determine changes
  let changed = false;

  // DESCRIPTION: seed ONLY if blank; otherwise leave untouched
  const descIsBlank = !String(exDesc || "").trim();
  const updateFields = {};
  if (descIsBlank) { updateFields.description = SEED_DESC; changed = true; }

  if (!sameText(newDOR,  exDOR))     { updateFields.customfield_10066 = newDOR;   changed = true; }
  if (!sameText(refsSafe, exRefs))   { updateFields.customfield_10067 = refsSafe; changed = true; }
  if (newRisk && !sameText(newRisk, exRisk)) { updateFields.customfield_10063 = newRisk; changed = true; }
  if (!sameText(newAssets, exAssets)) { updateFields.customfield_10065 = newAssets; changed = true; }
  if (!sameText(newTVI, exTVI))      { updateFields.customfield_10064 = newTVI;   changed = true; }

  if (!sameArray(newLabels, exLabels)) {
    updateFields.labels = newLabels; changed = true;
  }

  if (!changed && !FORCE_UPDATE) continue;

  out.push({ json: { issueKey: key, fields: updateFields } });
}

return out;

// Decide Update/Create (ROBUST)
// - Groups from "Tag Index" (else falls back to $input)
// - RRD issues from a Jira node named EXACTLY "Check RRD"
// - Emits: { ...group, exists, existingKey }

function got(name) {
  try {
    const arr = $items(name);
    return Array.isArray(arr) ? arr.map(i => i.json || {}) : [];
  } catch { return []; }
}

const groups = got("Tag Index").length ? got("Tag Index") : ($input.all() || []).map(i => i.json || {});
const searchIssues = got("Check RRD")
  .filter(it => (it.key || it.id) && (it.fields?.summary || it.summary));

const norm = s => String(s || '').replace(/\s+/g, ' ').trim().toLowerCase();
const newer = (a, b) => {
  const an = Number(String(a.id || '').replace(/\D/g, ''));
  const bn = Number(String(b.id || '').replace(/\D/g, ''));
  return (!Number.isNaN(an) && !Number.isNaN(bn)) ? (an >= bn ? a : b) : a;
};

// Exact-summary lookup (normalized)
const bySummary = new Map();
for (const issue of searchIssues) {
  const s = issue.fields?.summary ?? issue.summary ?? '';
  const n = norm(s);
  if (!n) continue;
  const prev = bySummary.get(n);
  bySummary.set(n, prev ? newer(issue, prev) : issue);
}

// --- Robust tokenization ---
// We split on " - " into segments and match all non-empty tokens against candidates.
// Special cases:
//  - ZAP: left is URL → reduce to host token
//  - Prowler: summary starts with "Prowler Alert - " → ignore that banner segment
function segmentsFromSummary(summary) {
  const raw = String(summary || '');
  const parts = raw.split(/\s-\s/).map(p => p.trim()).filter(Boolean);

  // ZAP: if first part looks like URL, reduce to host
  if (/^https?:\/\//i.test(parts[0] || '')) {
    const host = parts[0].replace(/^https?:\/\//i, '').replace(/\/.*$/, '');
    parts[0] = host;
  }

  // Prowler: drop the banner "Prowler Alert"
  if (/^prowler\s*alert$/i.test(parts[0] || '')) {
    parts.shift(); // remove "Prowler Alert"
  }

  // Kubescape: drop the banner "Kubescape Alert"
  if (/^kubescape\s*alert$/i.test(parts[0] || '')) {
    parts.shift();
  }

  // Split remaining parts further on whitespace to be resilient, but keep short phrases together
  // Heuristic: emit tokens that are at least 2 chars, ignoring punctuation-only
  const tokens = [];
  for (const p of parts) {
    const t = p.replace(/[^\p{L}\p{N}\-_/.: ]+/gu, ' ').trim(); // keep typical chars
    const bits = t.split(/\s+/).filter(Boolean);
    // prefer the whole segment as a token, but add select sub-bits for robustness
    if (t) tokens.push(t.toLowerCase());
    for (const b of bits) {
      if (b.length >= 2) tokens.push(b.toLowerCase());
    }
  }

  // De-dup
  return Array.from(new Set(tokens));
}

function fuzzyFind(summary) {
  const toks = segmentsFromSummary(summary);
  if (!toks.length) return null;

  // Score each candidate by how many tokens it contains; pick the newest among top score ties
  let best = null;
  let bestScore = -1;

  for (const issue of searchIssues) {
    const s = (issue.fields?.summary ?? issue.summary ?? '').toLowerCase();
    if (!s) continue;

    let score = 0;
    for (const tk of toks) {
      if (s.includes(tk)) score++;
    }

    if (score > bestScore) {
      best = issue; bestScore = score;
    } else if (score === bestScore && best) {
      best = newer(issue, best);
    }
  }

  // Require at least 2 token hits to avoid spurious matches (1 is too weak)
  if (best && bestScore >= Math.min(2, toks.length)) return best;
  return null;
}

// Build output
let out = groups.map(g => {
  const exact = bySummary.get(norm(g.summary));
  const hit = exact || fuzzyFind(g.summary);
  const existingKey = hit ? (hit.key || hit.id || null) : null;
  const exists = !!existingKey;
  return { json: { ...g, exists, existingKey } };
});

// Helpful debug when your RRD query returned nothing
if (!searchIssues.length) {
  out = out.map(it => ({
    json: { ...it.json, _debug: "No items from 'Check RRD'. Verify node name & JQL; enable 'Always Output Data' and set a high limit." }
  }));
}

return out;

// Apply Defaults — Webhook -> ES body query
// Reads exactly one input param: `tool` (single tool name or "all").
// Outputs one item per tool with: { index, tool, query }.
// In Elastic "Get many documents":
//   Index ID:        {{ $json.index }}
//   Options → Query: {{ $json.query }}

const ES_INDEX = 'security-findings'; // set your index name here
const DEFAULT_TOOLS = ['zaproxy','trufflehog','trivy','checkov','prowler','kubescape'];

const ALIASES = {
  zap: 'zaproxy', zaproxy: 'zaproxy',
  truffle: 'trufflehog', trufflehog: 'trufflehog',
  triv: 'trivy', trivy: 'trivy',
  ckv: 'checkov', checkov: 'checkov',
  prowler: 'prowler',
  kube: 'kubescape', kubescape: 'kubescape',
  all: 'all',
};

function getToolFromWebhook() {
  const j = $json || {};
  return j.tool ?? j.query?.tool ?? j.params?.tool ?? j.body?.tool ?? 'all';
}

function normalizeTool(raw) {
  const key = String(raw || '').trim().toLowerCase();
  return ALIASES[key] || key || 'all';
}

// Build a body query to match Document.tool == <tool>
