const statusCat     = cfg.statusCategory;              // e.g., Done or "Done"
const extraJql      = (cfg.extraJql || "").trim();     // free-form JQL to AND

// JQL-safe escaper: ONLY escape backslash + double-quote; normalize whitespace
const esc = (s) => {
  return String(s ?? "")
    .replace(/\\/g, '\\\\')   // backslash
    .replace(/"/g, '\\"')     // double quote
    .replace(/\r?\n/g, ' ')   // newlines -> space
    .replace(/\t/g, ' ')      // tabs -> space
    .trim();
};

// Nice-casing for labels like "Trivy", "Zaproxy"
const niceCase = (s) => {
  s = String(s ?? "").trim();
  return s ? s.charAt(0).toUpperCase() + s.slice(1).toLowerCase() : s;
};

// Quote statusCategory only if it contains whitespace
const formatStatusCat = (sc) => {
  if (sc == null) return null;
  const v = String(sc).trim();
  if (!v) return null;
  return /\s/.test(v) ? `"${esc(v)}"` : v;
};

function buildJql({ summary, tool }) {
  const parts = [
    `project = ${esc(rrdProject)}`,
    `summary ~ "${esc(summary)}"`
  ];

  if (requireLabel && tool) {
    parts.push(`labels in ("${esc(niceCase(tool))}")`);
  }
  if (sinceDays) {
    parts.push(`updated >= -${parseInt(sinceDays, 10)}d`);
  }
  const sc = formatStatusCat(statusCat);
  if (sc) {
    parts.push(`statusCategory != ${sc}`);
  }
  if (extraJql) {
    // extraJql is inserted as-is (assumed valid JQL fragment)
    parts.push(`(${extraJql})`);
  }

  return {
    jql: parts.join(" AND ") + " ORDER BY created DESC",
    parts,
    labelUsed: niceCase(tool || "")
  };
}

